using namespace std;

// Function to check if a directory exists
bool directoryExists(const char* path) {
    struct stat buffer;
    return (stat(path, &buffer) == 0 && S_ISDIR(buffer.st_mode));
}

// Function to create a directory with specific permissions
bool createDirectory(const char* path, mode_t permissions) {
    if (mkdir(path, permissions) == 0) {
        return true;
    }
    return false;
}

// Function to set directory permissions
bool setDirectoryPermissions(const char* path, mode_t permissions) {
    if (chmod(path, permissions) == 0) {
        return true;
    }
    return false;
}

// Function to check if a directory is accessible
bool isDirectoryAccessible(const char* path) {
    return (access(path, F_OK) == 0);
}

// Function to block unauthorized access to a specific directory
void blockDirectoryAccess(const char* directoryPath) {
    // Check if the directory exists
    if (!directoryExists(directoryPath)) {
        cout << "Error: Directory does not exist." << endl;
        return;
    }

    // Create a new directory with restricted permissions
    mode_t restrictedPermissions = S_IRUSR | S_IWUSR;  // Read and write for owner only
    if (!createDirectory(directoryPath, restrictedPermissions)) {
        cout << "Error: Failed to create directory with restricted permissions." << endl;
        return;
    }

    // Set the directory permissions to restricted
    if (!setDirectoryPermissions(directoryPath, restrictedPermissions)) {
        cout << "Error: Failed to set directory permissions." << endl;
        return;
    }

    cout << "Directory access blocked successfully." << endl;
}

// Main function
int main() {
    const char* directoryPath = "/path/to/your/directory";  // Replace with the actual directory path

    // Block unauthorized access to the specified directory
    blockDirectoryAccess(directoryPath);

    return 0;
}

