#!/bin/bash
# Function to read the contents of a file
read_file() {
    local file="$1"
    local contents=$(cat "$file")
    echo "$contents"
}
# Function to modify the contents of a file in-place
modify_file() {
    local file="$1"
    local contents="$2"
    echo "$contents" > "$file"
}
# Function to log changes to a file
log_changes() {
    local file="$1"
    local changes="$2"
    echo "Changes made to $file: $changes" >> "$file.log"
}
# Main function to change the state of a system by modifying a configuration file
change_state() {
    local file="$1"
    local new_value="$2"
    local old_value=$(read_file "$file")
    local changes="Old value: $old_value, New value: $new_value"
    modify_file "$file" "$new_value"
    log_changes "$file" "$changes"
}
# Example usage
change_state "/etc/hostname" "new-hostname"

